import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const marker = "AE_PACK_06_START";
const packName = "Animated Effects Pack 06";

function fail(message) {
  console.error("\nERROR:", message);
  process.exit(1);
}

if (!fs.existsSync(path.join(root, "pnpm-workspace.yaml"))) {
  fail("Uruchom plik z głównego katalogu aplikacja-turnieje-live.");
}

const required = [
  "artifacts/animated-effects/src/main.ts",
  "artifacts/animated-effects/src/style.css",
  "artifacts/animated-effects/src/effects/variants.ts",
  "artifacts/animated-effects/package.json",
];
for (const relative of required) {
  if (!fs.existsSync(path.join(root, relative))) fail(`Brak wymaganego pliku: ${relative}`);
}

const stylePath = path.join(root, "artifacts/animated-effects/src/style.css");
const originalStyle = fs.readFileSync(stylePath, "utf8");
if (originalStyle.includes(marker)) {
  console.log("Pack 06 jest już zainstalowany.");
  process.exit(0);
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-").replace("T", "_").replace("Z", "");
const backupRoot = path.join(root, ".ae-pack-backup", `pack-06-${stamp}`);
const payload = {"artifacts/animated-effects/src/core/types.ts": "", "artifacts/animated-effects/src/editor/state.ts": "", "artifacts/animated-effects/src/effects/registry.ts": "", "artifacts/animated-effects/src/effects/modules/pack06.ts": "", "artifacts/animated-effects/src/effects/modules/pack06Variants.ts": "", "artifacts/animated-effects/src/scenes/scenes.ts": "", "artifacts/animated-effects/src/scenes/presets.ts": "", "artifacts/animated-effects/src/media/mediaExport.ts": "", "artifacts/animated-effects/src/pack06/install.ts": ""};
const extraTouched = [
  "artifacts/animated-effects/src/main.ts",
  "artifacts/animated-effects/src/style.css",
  "artifacts/animated-effects/src/effects/variants.ts",
  "artifacts/animated-effects/package.json",
  "pnpm-lock.yaml",
  "artifacts/animated-effects/AE_PACK_06.json",
];
const allTouched = [...new Set([...Object.keys(payload), ...extraTouched])];
const existed = [];
for (const relative of allTouched) {
  const source = path.join(root, relative);
  if (!fs.existsSync(source)) continue;
  existed.push(relative);
  const dest = path.join(backupRoot, relative);
  fs.mkdirSync(path.dirname(dest), { recursive:true });
  fs.copyFileSync(source, dest);
}
fs.mkdirSync(backupRoot, { recursive:true });
fs.writeFileSync(path.join(backupRoot, "backup-manifest.json"), JSON.stringify({packName,existed,allTouched}, null, 2) + "\n", "utf8");

for (const [relative, encoded] of Object.entries(payload)) {
  const dest = path.join(root, relative);
  fs.mkdirSync(path.dirname(dest), { recursive:true });
  fs.writeFileSync(dest, Buffer.from(encoded, "base64"));
}

// Merge Pack 06 variants into the existing variant catalog.
const variantsPath = path.join(root, "artifacts/animated-effects/src/effects/variants.ts");
let variants = fs.readFileSync(variantsPath, "utf8");
if (!variants.includes('from "./modules/pack06Variants"')) {
  const anchor = 'import type {\n  EffectSettings,\n} from "../core/types";';
  if (!variants.includes(anchor)) fail("Nie znaleziono oczekiwanego importu w variants.ts. Uruchom rollback.");
  variants = variants.replace(anchor, `${anchor}\n\nimport {\n  pack06EffectVariantCatalog,\n} from "./modules/pack06Variants";`);
}
if (variants.includes("return effectVariantCatalog[effectId] ?? [];")) {
  variants = variants.replace("return effectVariantCatalog[effectId] ?? [];", "return pack06EffectVariantCatalog[effectId] ?? effectVariantCatalog[effectId] ?? [];");
} else if (!variants.includes("pack06EffectVariantCatalog[effectId]")) {
  fail("Nie znaleziono getEffectVariants() w oczekiwanej wersji. Uruchom rollback.");
}
fs.writeFileSync(variantsPath, variants, "utf8");

// Patch main.ts minimally: install Pack 06, re-render library on state change,
// and extend search to tags + variant names.
const mainPath = path.join(root, "artifacts/animated-effects/src/main.ts");
let main = fs.readFileSync(mainPath, "utf8");
if (!main.includes('from "./pack06/install"')) {
  const first = 'import "./style.css";';
  if (!main.includes(first)) fail("Nie znaleziono początku main.ts. Uruchom rollback.");
  main = main.replace(first, `${first}\n\nimport {\n  installPack06,\n} from "./pack06/install";`);
}
const oldRender = `function renderEditor(): void {\n  renderPreview();\n  renderLayers();\n  renderStatus();`;
if (main.includes(oldRender)) {
  main = main.replace(oldRender, `function renderEditor(): void {\n  renderEffectLibrary();\n  renderPreview();\n  renderLayers();\n  renderStatus();`);
}
const oldSearch = `        const searchable = [\n          definition.name,\n          definition.id,\n        ]`;
if (main.includes(oldSearch)) {
  main = main.replace(oldSearch, `        const searchable = [\n          definition.name,\n          definition.id,\n          definition.category,\n          ...definition.tags,\n          ...getEffectVariants(\n            definition.id,\n          ).map(\n            (variant) =>\n              variant.name,\n          ),\n        ]`);
}
if (!main.includes("installPack06();")) {
  const initial = `addEffect(\n  "rainfall",\n);`;
  if (!main.includes(initial)) fail("Nie znaleziono inicjalizacji rainfall w main.ts. Uruchom rollback.");
  main = main.replace(initial, `${initial}\n\ninstallPack06();`);
}
fs.writeFileSync(mainPath, main, "utf8");

// CSS last, so Pack 06 responsive rules win.
fs.writeFileSync(stylePath, originalStyle.trimEnd() + "\n\n" + "/* === AE_PACK_06_START === */\n.ae-pack06-header-actions{flex-wrap:wrap}\n.ae-pack06-header-group{display:flex;flex-wrap:wrap;gap:6px}\n#pack06-performance.is-warning{border-color:rgba(240,184,90,.5);color:#f0b85a}\n.ae-effect-card{grid-template-columns:auto minmax(0,1fr) auto;gap:6px}\n.ae-effect-card.is-on-scene{border-color:rgba(87,199,255,.42);background:linear-gradient(105deg,rgba(87,199,255,.075),rgba(21,29,42,.98) 46%)}\n.ae-pack06-favorite{width:28px;border:0;background:transparent;color:rgba(210,220,235,.55);font-size:18px;cursor:pointer}\n.ae-pack06-favorite:hover{color:#f0b85a}\n.ae-pack06-scene-badge{display:inline-flex;align-items:center;min-height:18px;padding:0 6px;border:1px solid rgba(85,214,194,.34);border-radius:999px;background:rgba(85,214,194,.08);color:#7ce3d3;font-size:8px;font-weight:800;white-space:nowrap}\n.ae-pack06-card-actions{display:flex;align-items:center;gap:4px}\n.ae-pack06-minus,.ae-pack06-count{min-width:38px;height:44px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.14);border-radius:9px;background:#151d2a;color:#c5cfde;font-size:13px;font-weight:800;cursor:pointer}\n.ae-pack06-minus:disabled{opacity:.35;cursor:not-allowed}.ae-pack06-count{color:#78d8ff}\n.ae-layer-row{min-width:0}.ae-layer-row.is-locked{border-style:dashed}.ae-layer-row.is-solo{box-shadow:inset 3px 0 0 #78d8ff}.ae-layer-row.is-dragging{opacity:.45}\n.ae-layer-actions{min-width:0;grid-template-columns:repeat(7,40px);gap:5px}.ae-layer-actions .ae-icon-button{width:40px;min-width:40px}\n.effect-preview.is-pack06-paused *,.effect-preview.is-pack06-paused *::before,.effect-preview.is-pack06-paused *::after{animation-play-state:paused!important}\n.ae-pack06-inspector{margin-bottom:12px}.ae-pack06-inspector-title{display:grid;gap:2px;margin-bottom:10px}.ae-pack06-inspector-title span{color:#8994a8;font-size:11px}.ae-pack06-seed-row,.ae-pack06-copy-row{display:flex;gap:8px}.ae-pack06-seed-row input{min-width:0;flex:1}.ae-pack06-copy-row{margin-top:10px}\n.ae-media-export{padding:0 18px 18px}.ae-media-section{margin-top:14px;padding-top:14px;border-top:1px solid rgba(255,255,255,.08)}.ae-media-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px;margin-bottom:12px}.ae-media-grid label{display:grid;gap:5px;color:#aeb9ca;font-size:11px}.ae-media-grid input,.ae-media-grid select{width:100%;min-width:0}.ae-media-actions{display:flex;flex-wrap:wrap;gap:8px}.ae-media-export progress{width:100%;margin:12px 0 6px}.ae-gif-preview{display:block;width:100%;max-height:360px;object-fit:contain;margin-top:12px;border-radius:10px;background:repeating-conic-gradient(#151b27 0 25%,#202838 0 50%) 50%/18px 18px}\n@media(max-width:1500px){.ae-layer-row{grid-template-columns:minmax(0,1fr);align-items:stretch}.ae-layer-actions{width:100%;grid-template-columns:repeat(7,minmax(38px,1fr))}.ae-layer-actions .ae-icon-button{width:100%;min-width:38px}}\n@media(max-width:1260px){.ae-layer-list{padding-left:10px;padding-right:10px}.ae-layer-row{gap:8px;padding:8px}.ae-layer-copy strong,.ae-layer-copy small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ae-layer-actions{grid-template-columns:repeat(4,minmax(40px,1fr))}}\n/* === AE_PACK_06_END === */\n".trim() + "\n", "utf8");

// Media export dependencies.
const packagePath = path.join(root, "artifacts/animated-effects/package.json");
const pkg = JSON.parse(fs.readFileSync(packagePath, "utf8"));
pkg.dependencies = { ...(pkg.dependencies ?? {}), "gifenc":"^1.0.3", "html-to-image":"^1.11.13" };
fs.writeFileSync(packagePath, JSON.stringify(pkg, null, 2) + "\n", "utf8");

const manifestPath = path.join(root, "artifacts/animated-effects/AE_PACK_06.json");
fs.writeFileSync(manifestPath, JSON.stringify({
  pack:packName,
  installedAt:new Date().toISOString(),
  backup:path.relative(root, backupRoot),
  features:[
    "16 new effects (49 -> 65)",
    "4 variants for every Pack 06 effect",
    "quick - / N× / + library controls",
    "favorites / scene filter / sorting / tag+variant search",
    "duplicate / rename / lock / multi-solo / drag reorder",
    "Undo / Redo + slider history batching",
    "seed controls + reroll all",
    "scene JSON save/load + recovery autosave",
    "8 scene presets",
    "preview pause + performance estimate",
    "PNG and GIF export",
  ],
}, null, 2) + "\n", "utf8");

// One-command rollback.
const rollbackPath = path.join(root, "ae-pack-06-rollback.mjs");
const rollback = `import fs from "node:fs";\nimport path from "node:path";\nconst root=process.cwd();\nconst backupRoot=${JSON.stringify(backupRoot)};\nconst manifestPath=path.join(backupRoot,"backup-manifest.json");\nif(!fs.existsSync(manifestPath)){console.error("Brak manifestu backupu:",manifestPath);process.exit(1)}\nconst manifest=JSON.parse(fs.readFileSync(manifestPath,"utf8"));\nconst existed=new Set(manifest.existed);\nfor(const relative of manifest.allTouched){const target=path.join(root,relative);const backup=path.join(backupRoot,relative);if(existed.has(relative)){if(!fs.existsSync(backup)){console.error("Brak backupu:",relative);process.exit(1)}fs.mkdirSync(path.dirname(target),{recursive:true});fs.copyFileSync(backup,target)}else{fs.rmSync(target,{recursive:true,force:true})}}\nconsole.log("Pack 06 cofnięty. Uruchom: pnpm install");\n`;
fs.writeFileSync(rollbackPath, rollback, "utf8");

console.log("\n==========================================");
console.log(" Animated Effects Pack 06: INSTALLED");
console.log("==========================================");
console.log("Backup:", path.relative(root, backupRoot));
console.log("Rollback: .\\ae-pack-06-rollback.mjs");
console.log("\nTeraz uruchom:");
console.log("  pnpm install");
console.log('  pnpm --filter animated-effects run typecheck');
console.log('  pnpm --filter animated-effects run build');
console.log("\nNie commituj przed testami UI.");
